export const duckingDefaults={threshold:-24,ratio:4,attack:.02,release:.25};
export function validDucking(buses){const byId=new Map(buses.map(b=>[b.id,b])),reaches=(from,to,seen=new Set())=>{if(from===to)return true;if(seen.has(from))return false;seen.add(from);const b=byId.get(from);return [b?.parent,...(b?.sends||[]).map(s=>s.bus)].filter(Boolean).some(id=>reaches(id,to,seen));};const visiting=new Set(),done=new Set(),visit=id=>{if(visiting.has(id))return false;if(done.has(id))return true;visiting.add(id);const source=byId.get(id)?.ducking?.source;if(source&&(!byId.has(source)||!visit(source)))return false;visiting.delete(id);done.add(id);return true;};return buses.every(b=>visit(b.id))&&buses.every(b=>{const d=b.ducking;return d===undefined||d&&byId.has(d.source)&&!reaches(b.id,d.source)&&typeof d.enabled==='boolean'&&Number.isFinite(d.threshold)&&d.threshold>=-80&&d.threshold<=0&&Number.isFinite(d.ratio)&&d.ratio>=1&&d.ratio<=100&&Number.isFinite(d.attack)&&d.attack>=.001&&d.attack<=10&&Number.isFinite(d.release)&&d.release>=.001&&d.release<=10;});}
export class DuckingEnvelope{
  constructor(){this.reductionDb=0;this.gain=1;}
  update(rms,delta,settings){if(!Number.isFinite(rms)||rms<0||!Number.isFinite(delta)||delta<0)throw Error('사이드체인 신호·시간 오류');const db=20*Math.log10(Math.max(rms,1e-9)),target=settings.enabled?Math.max(0,db-settings.threshold)*(1-1/settings.ratio):0,seconds=target>this.reductionDb?settings.attack:settings.release,alpha=1-Math.exp(-delta/seconds);this.reductionDb+=(target-this.reductionDb)*alpha;this.gain=10**(-this.reductionDb/20);return this.gain;}
}
export function renderDucking(editor,bus,section){const doc=section.ownerDocument,group=doc.createElement('fieldset'),title=doc.createElement('legend');title.textContent='사이드체인';group.append(title);const edit=fn=>{editor.stopPreview();editor.edit(d=>fn(d.buses.find(b=>b.id===bus.id)));};if(!bus.ducking){const button=doc.createElement('button');button.textContent='사이드체인 추가';button.onclick=()=>{const source=editor.doc.data.buses.find(b=>b.id!==bus.id&&b.parent===bus.parent);if(!source)return editor.hooks.error('독립된 신호 버스가 필요해요.');edit(b=>b.ducking={...duckingDefaults,source:source.id,enabled:true});};group.append(button);}else{const select=doc.createElement('select');select.setAttribute('aria-label','사이드체인 신호 버스');for(const b of editor.doc.data.buses.filter(b=>b.id!==bus.id)){const o=doc.createElement('option');o.value=b.id;o.textContent=b.name;select.append(o);}select.value=bus.ducking.source;select.onchange=()=>edit(b=>b.ducking.source=select.value);group.append(select);for(const key of ['enabled','threshold','ratio','attack','release']){const label=doc.createElement('label'),input=doc.createElement('input');label.textContent={enabled:'활성화',threshold:'임계값 · dB',ratio:'비율',attack:'Attack · 초',release:'Release · 초'}[key];input.type=key==='enabled'?'checkbox':'number';input.step='.01';if(key==='enabled')input.checked=bus.ducking[key];else input.value=bus.ducking[key];input.onchange=()=>edit(b=>b.ducking[key]=key==='enabled'?input.checked:Number(input.value));label.append(input);group.append(label);}const remove=doc.createElement('button');remove.textContent='사이드체인 제거';remove.onclick=()=>edit(b=>delete b.ducking);group.append(remove);}section.append(group);}
